-- Recetario para 2 · Supabase
-- Pega TODO este archivo en Supabase → SQL Editor → New query → Run.
-- Se puede ejecutar más de una vez sin romper nada.

-- ============ Tablas ============
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 30),
  created_at timestamptz not null default now()
);

create table if not exists public.recipes (
  id text primary key,
  cat text not null check (cat in ('rapidas','diario','finde','salsas')),
  title text not null,
  time text not null default '',
  lvl text not null default 'Fácil',
  light boolean not null default false,
  blurb text not null default '',
  ing jsonb not null default '[]',
  steps jsonb not null default '[]',
  tip text,
  link text,
  src text,
  photo_path text,
  pos integer not null default 10000,
  created_by uuid default auth.uid() references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.favorites (
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  recipe_id text not null references public.recipes(id) on delete cascade on update cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, recipe_id)
);

create table if not exists public.comments (
  id bigint generated always as identity primary key,
  recipe_id text not null references public.recipes(id) on delete cascade on update cascade,
  user_id uuid not null default auth.uid() references public.profiles(id) on delete cascade,
  body text not null check (char_length(body) between 1 and 1000),
  created_at timestamptz not null default now()
);
create index if not exists comments_recipe_idx on public.comments(recipe_id, created_at);

-- updated_at automático
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;
drop trigger if exists recipes_touch on public.recipes;
create trigger recipes_touch before update on public.recipes
  for each row execute function public.touch_updated_at();

-- ============ Seguridad (RLS) ============
alter table public.profiles  enable row level security;
alter table public.recipes   enable row level security;
alter table public.favorites enable row level security;
alter table public.comments  enable row level security;

-- Perfiles: los ven los usuarios con sesión; cada uno edita el suyo
drop policy if exists "profiles_read"   on public.profiles;
drop policy if exists "profiles_insert" on public.profiles;
drop policy if exists "profiles_update" on public.profiles;
create policy "profiles_read"   on public.profiles for select to authenticated using (true);
create policy "profiles_insert" on public.profiles for insert to authenticated with check (id = auth.uid());
create policy "profiles_update" on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());

-- Recetas: cualquiera las lee (como ahora); con sesión, cualquiera de los dos las crea, edita o borra
drop policy if exists "recipes_read"   on public.recipes;
drop policy if exists "recipes_insert" on public.recipes;
drop policy if exists "recipes_update" on public.recipes;
drop policy if exists "recipes_delete" on public.recipes;
create policy "recipes_read"   on public.recipes for select to anon, authenticated using (true);
create policy "recipes_insert" on public.recipes for insert to authenticated with check (true);
create policy "recipes_update" on public.recipes for update to authenticated using (true) with check (true);
create policy "recipes_delete" on public.recipes for delete to authenticated using (true);

-- Favoritas: cada uno solo ve y toca las suyas
drop policy if exists "favorites_own" on public.favorites;
create policy "favorites_own" on public.favorites for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Comentarios: los ven los usuarios con sesión; cada uno publica y borra los suyos
drop policy if exists "comments_read"   on public.comments;
drop policy if exists "comments_insert" on public.comments;
drop policy if exists "comments_delete" on public.comments;
create policy "comments_read"   on public.comments for select to authenticated using (true);
create policy "comments_insert" on public.comments for insert to authenticated with check (user_id = auth.uid());
create policy "comments_delete" on public.comments for delete to authenticated using (user_id = auth.uid());

-- ============ Fotos ============
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('fotos', 'fotos', true, 5242880, array['image/jpeg','image/png','image/webp'])
on conflict (id) do nothing;

drop policy if exists "fotos_insert" on storage.objects;
drop policy if exists "fotos_update" on storage.objects;
drop policy if exists "fotos_delete" on storage.objects;
create policy "fotos_insert" on storage.objects for insert to authenticated with check (bucket_id = 'fotos');
create policy "fotos_update" on storage.objects for update to authenticated using (bucket_id = 'fotos');
create policy "fotos_delete" on storage.objects for delete to authenticated using (bucket_id = 'fotos');
